update public.pagelle p set migliore_in_campo = (p.id = (select x.id from public.pagelle x where x.match_id = p.match_id and x.voto is not null order by x.voto desc, x.migliore_in_campo desc, x.id limit 1))
 where p.match_id in (1219,1259,1283,1286,1309,1343,1351,1348,1365,1392,1389,1390,1376,1433,1441,1476,1509,1520);
